const {MeshJs} = require(process.argv[1]);
const cube=MeshJs.cube(1), empty=new MeshJs();
let failures=0;
try {
  for (const [shape,mesh] of [["cube",cube],["empty",empty]]) {
    for (const approximate of [false,true]) {
      for (let slot=0;slot<3;slot++) {
        for (const value of [-1,1.5,NaN,Infinity,4294967296]) {
          const limits=[1,1,64];limits[slot]=value;
          let result;
          try {
            const out=mesh.minkowskiSumWithLimits(mesh,approximate,...limits);
            result={outcome:"success",certainty:out.certainty};
            out.intoMesh().free();
          } catch(error) {result={outcome:"error",name:error.name,code:error.code,message:error.message};}
          console.log(JSON.stringify({shape,approximate,slot,value:String(value),...result}));
          if(result.outcome!=="error" || result.name!=="GeometryError" || result.code!=="invalid_input") failures++;
        }
      }
    }
  }
} finally {cube.free();empty.free();}
console.log(JSON.stringify({invalid_count_cases:60,failures}));
process.exitCode=failures ? 1 : 0;
